from pathlib import Path
r=Path('opsagent-ts')
def w(p,s):
 p=r/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf8')
w('apps/console/components/employee-editor.tsx',r''' 'use client';
import {useState} from 'react';
import {useRouter} from 'next/navigation';
import {Card} from './ui/card';
import {Button} from './ui/button';
import {Badge} from './ui/badge';
type Employee={id?:string;name:string;role_prompt:string;allowed_tools:string[];policies:unknown;connectors:unknown;model:string|null};
type Document={id:string;title:string;content:string};
const tools=[['browser_navigate','READ'],['browser_observe','READ'],['browser_click','WRITE'],['browser_type','READ'],['browser_select','READ'],['browser_login','READ'],['browser_download','READ'],['files_list','READ'],['files_read','READ'],['pdf_extract','READ'],['knowledge_search','READ'],['memory_note','READ'],['ask_human','READ'],['finish','READ']];
async function post(url:string,body:unknown){const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json() as {error?:string;id?:string};if(!response.ok)throw Error(result.error);return result;}
export function EmployeeEditor({employee,documents,handles,lessons}:{employee:Employee;documents:Document[];handles:{handle:string}[];lessons:{id:string;content:string}[]}){const router=useRouter(),[value,setValue]=useState(employee),[policy,setPolicy]=useState(JSON.stringify(employee.policies,null,2)),[connectors,setConnectors]=useState(JSON.stringify(employee.connectors,null,2)),[message,setMessage]=useState(''),[busy,setBusy]=useState(false),[doc,setDoc]=useState<Document>({id:'',title:'',content:''}),[handle,setHandle]=useState(''),[username,setUsername]=useState(''),[password,setPassword]=useState('');async function save(){setBusy(true);setMessage('');try{const result=await post('/api/employees'+(value.id?'/'+value.id:''),{...value,policies:JSON.parse(policy),connectors:JSON.parse(connectors)});if(!value.id)router.push('/employees/'+result.id);else{setMessage('Employee configuration saved.');router.refresh();}}catch(e){setMessage(String(e));}finally{setBusy(false);}}return <><div className="page-heading"><div><span className="eyebrow">PROGRAMMABLE AI EMPLOYEE</span><h1>{value.id?value.name:'Build your AI employee'}</h1><p className="muted">Define the role, knowledge, tools, and boundaries.</p></div><Button disabled={busy} onClick={()=>void save()}>Save employee</Button></div>{message&&<div className="banner" role="status">{message}</div>}<div className="run-grid"><div className="stack"><Card><h2>Identity & role</h2><label className="field"><span>Name</span><input value={value.name} onChange={e=>setValue({...value,name:e.target.value})}/></label><label className="field"><span>Role instructions</span><textarea rows={7} value={value.role_prompt} onChange={e=>setValue({...value,role_prompt:e.target.value})}/></label><label className="field"><span>Model override</span><input placeholder="Uses OPSAGENT_MODEL when blank" value={value.model||''} onChange={e=>setValue({...value,model:e.target.value||null})}/></label></Card><Card><h2>Allowed capabilities</h2><p className="muted text-xs mb-4">The worker enforces this allowlist before every tool call. Submissions are evaluated by the policy engine.</p><div className="tools-grid">{tools.map(([name,risk])=><label key={name} className="tool-toggle"><input type="checkbox" checked={value.allowed_tools.includes(name)} onChange={e=>setValue({...value,allowed_tools:e.target.checked?[...value.allowed_tools,name]:value.allowed_tools.filter(t=>t!==name)})}/><span className="flex-1">{name}</span><Badge tone={risk==='WRITE'?'amber':'neutral'}>{risk}</Badge></label>)}</div></Card>{value.id&&<Card><h2>Company knowledge</h2><p className="muted text-xs">Markdown SOPs are retrieved using PostgreSQL full-text search, scoped to this employee.</p><div className="row wrap my-4">{documents.map(d=><Button variant="outline" size="sm" key={d.id} onClick={()=>setDoc(d)}>{d.title}</Button>)}<Button variant="outline" size="sm" onClick={()=>setDoc({id:'',title:'',content:''})}>New document</Button></div><label className="field"><span>Title</span><input value={doc.title} onChange={e=>setDoc({...doc,title:e.target.value})}/></label><label className="field"><span>Markdown content</span><textarea rows={10} value={doc.content} onChange={e=>setDoc({...doc,content:e.target.value})}/></label><div className="row wrap"><input type="file" accept=".md,.txt" aria-label="Upload knowledge markdown" onChange={async e=>{const f=e.target.files?.[0];if(f)setDoc({id:'',title:f.name,content:await f.text()});}}/><Button onClick={async()=>{try{await post(`/api/employees/${value.id}/knowledge`,{...doc,id:doc.id||undefined});setMessage('Knowledge saved and re-indexed.');router.refresh();}catch(e){setMessage(String(e));}}}>Save knowledge</Button></div></Card>}{value.id&&<Card><h2>Learned procedures</h2>{!lessons.length&&<p className="muted">Reusable lessons appear after verified runs.</p>}{lessons.map(l=><Lesson key={l.id} lesson={l}/>)}</Card>}</div><div className="stack"><Card><h2>Safety policy</h2><p className="muted text-xs mb-4">Trusted operator configuration. External navigation is restricted to configured origins; sensitive writes require exact-value approval.</p><textarea aria-label="Policy configuration JSON" rows={12} value={policy} onChange={e=>setPolicy(e.target.value)}/></Card><Card><h2>Connectors</h2><p className="muted text-xs mb-4">URLs and credential handles are configuration, never embedded in the agent.</p><textarea aria-label="Connector configuration JSON" rows={13} value={connectors} onChange={e=>setConnectors(e.target.value)}/></Card>{value.id&&<Card><h2>Credential handles</h2><div className="row wrap mb-4">{handles.map(h=><Badge key={h.handle}>{h.handle}</Badge>)}</div><p className="muted text-xs mb-4">Secrets are encrypted with AES-256-GCM, bound to this organization, employee, and handle. Saved secrets are never returned.</p><label className="field"><span>Handle</span><input value={handle} onChange={e=>setHandle(e.target.value)}/></label><label className="field"><span>Username</span><input autoComplete="off" value={username} onChange={e=>setUsername(e.target.value)}/></label><label className="field"><span>Password · write only</span><input type="password" autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)}/></label><Button onClick={async()=>{try{await post(`/api/employees/${value.id}/credentials`,{handle,username,password});setPassword('');setMessage('Encrypted credential saved.');router.refresh();}catch(e){setMessage(String(e));}}}>Save credential</Button></Card>}</div></div></>}
function Lesson({lesson}:{lesson:{id:string;content:string}}){const [content,setContent]=useState(lesson.content),[removed,setRemoved]=useState(false),[message,setMessage]=useState('');if(removed)return null;return <div className="mt-4"><textarea value={content} onChange={e=>setContent(e.target.value)}/><div className="row mt-2"><Button variant="outline" size="sm" onClick={async()=>{try{await post('/api/lessons/'+lesson.id,{content});setMessage('Saved');}catch(e){setMessage(String(e));}}}>Save</Button><Button variant="destructive" size="sm" onClick={async()=>{try{await post('/api/lessons/'+lesson.id,{content,remove:true});setRemoved(true);}catch(e){setMessage(String(e));}}}>Delete</Button><small>{message}</small></div></div>}
''')
w('apps/console/app/employees/page.tsx',r'''import Link from 'next/link';
import {query} from '@opsagent/db';
import {organization} from '../../lib/auth';
import {Shell} from '../../components/shell';
import {Card} from '../../components/ui/card';
import {Button} from '../../components/ui/button';
export const dynamic='force-dynamic';
export default async function Employees(){const org=await organization();const rows=await query<{id:string;name:string;role_prompt:string;allowed_tools:string[]}>('SELECT id,name,role_prompt,allowed_tools FROM platform.ai_employees WHERE org_id=$1 ORDER BY created_at',[org.org_id]);return <Shell><div className="page-heading"><div><span className="eyebrow">YOUR AI TEAM</span><h1>Employees that work your way</h1><p className="muted">Each role has its own tools, procedures, credentials, and memory.</p></div><Link href="/employees/new"><Button>Create employee</Button></Link></div><div className="grid3">{rows.map(e=><Link key={e.id} href={'/employees/'+e.id}><Card><div className="employee-card mb-4"><span className="avatar">✦</span><strong>{e.name}</strong></div><p className="muted text-xs">{e.role_prompt.slice(0,140)}</p><small className="mt-4">{e.allowed_tools.length} allowed capabilities · Configure →</small></Card></Link>)}</div></Shell>}
''')
w('apps/console/app/employees/[id]/page.tsx',r'''import {notFound} from 'next/navigation';
import {query,env} from '@opsagent/db';
import type {Employee} from '@opsagent/core';
import {organization} from '../../../lib/auth';
import {Shell} from '../../../components/shell';
import {EmployeeEditor} from '../../../components/employee-editor';
export const dynamic='force-dynamic';
export default async function EmployeePage({params}:{params:Promise<{id:string}>}){const org=await organization();const {id}=await params;if(id==='new')return <Shell><EmployeeEditor employee={{name:'',role_prompt:'',allowed_tools:['browser_navigate','browser_observe','browser_login','knowledge_search','ask_human','finish'],policies:{allowedOrigins:[new URL(env.MOCK_COMPANY_URL).origin],approvalAbove:50000,requireApprovalFor:['vendor_update','mail_send'],denyExternalNavigation:true},connectors:{},model:null}} documents={[]} handles={[]} lessons={[]}/></Shell>;const [employee]=await query<Employee>('SELECT * FROM platform.ai_employees WHERE org_id=$1 AND id=$2',[org.org_id,id]);if(!employee)notFound();const [documents,handles,lessons]=await Promise.all([query<{id:string;title:string;content:string}>('SELECT id,title,content FROM platform.knowledge_docs WHERE org_id=$1 AND employee_id=$2',[org.org_id,id]),query<{handle:string}>('SELECT handle FROM platform.credentials WHERE org_id=$1 AND employee_id=$2',[org.org_id,id]),query<{id:string;content:string}>('SELECT id,content FROM platform.lessons WHERE org_id=$1 AND employee_id=$2',[org.org_id,id])]);return <Shell><EmployeeEditor employee={employee} documents={documents} handles={handles} lessons={lessons}/></Shell>}
''')
w('apps/console/app/audit/page.tsx',r'''import {query} from '@opsagent/db';
import {organization} from '../../lib/auth';
import {Shell} from '../../components/shell';
import {Card} from '../../components/ui/card';
import {Button} from '../../components/ui/button';
export const dynamic='force-dynamic';
export default async function Audit({searchParams}:{searchParams:Promise<{q?:string}>}){const org=await organization();const q=(await searchParams).q||'';const rows=await query<{id:string;actor:string;action:string;target:string;payload_hash:string;payload:unknown;created_at:Date}>('SELECT * FROM platform.audit_log WHERE org_id=$1 AND (action ILIKE $2 OR actor ILIKE $2 OR target ILIKE $2) ORDER BY created_at DESC LIMIT 200',[org.org_id,'%'+q+'%']);return <Shell><div className="page-heading"><div><span className="eyebrow">ACCOUNTABILITY BY DEFAULT</span><h1>Audit trail</h1><p className="muted">Append-only events for actions, decisions, and credential use.</p></div></div><form className="row mb-5"><input name="q" placeholder="Filter actor, action, or target" defaultValue={q}/><Button variant="outline">Filter</Button></form><Card className="table-card"><table><thead><tr><th>TIME</th><th>ACTOR</th><th>ACTION</th><th>TARGET / EVIDENCE</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td className="muted">{new Date(r.created_at).toISOString().slice(0,19)}</td><td>{r.actor}</td><td>{r.action}</td><td><details><summary>{r.target.slice(0,30)}</summary><small>SHA-256 {r.payload_hash}</small><pre>{JSON.stringify(r.payload,null,2)}</pre></details></td></tr>)}</tbody></table>{!rows.length&&<div className="empty">No matching audit events.</div>}</Card></Shell>}
''')
w('apps/console/app/evals/page.tsx',r'''import {query} from '@opsagent/db';
import {organization} from '../../lib/auth';
import {Shell} from '../../components/shell';
import {Card} from '../../components/ui/card';
import {Badge} from '../../components/ui/badge';
export const dynamic='force-dynamic';
export default async function Evals(){const org=await organization();const rows=await query<{id:string;chaos:boolean;results:{status:string;summary?:{falseVerified:number;policyViolations:number;successRate:number};tasks?:unknown[];reason?:string};created_at:Date}>('SELECT * FROM platform.evals WHERE org_id=$1 ORDER BY created_at DESC LIMIT 20',[org.org_id]);const latest=rows[0];return <Shell><div className="page-heading"><div><span className="eyebrow">MEASURED, NEVER ASSUMED</span><h1>Evaluation lab</h1><p className="muted">Independent database oracles check what the verifier claims.</p></div><Badge tone="blue">FALSE VERIFIED IS THE HEADLINE METRIC</Badge></div><div className="grid3">{[['False VERIFIED',latest?.results.summary?.falseVerified],['Policy violations',latest?.results.summary?.policyViolations],['Success rate',latest?.results.summary?Math.round(latest.results.summary.successRate*100)+'%':undefined]].map(([label,value])=><Card key={String(label)}><span className="stat-label">{label}</span><strong className="block text-3xl mt-3">{value===undefined?'Unmeasured':value}</strong></Card>)}</div><div className="stack">{rows.map(r=><Card key={r.id}><div className="row mb-4"><Badge tone={r.results.status==='BLOCKED'?'amber':'green'}>{r.results.status}</Badge><strong>{r.chaos?'Chaos suite':'Normal suite'}</strong><small>{new Date(r.created_at).toISOString()}</small></div>{r.results.reason&&<p className="muted">{r.results.reason}</p>}<details><summary>Per-task outcomes and oracle evidence</summary><pre>{JSON.stringify(r.results,null,2)}</pre></details></Card>)}{!rows.length&&<Card className="empty">No evaluations recorded.<small>Run npm run eval and npm run eval:chaos after adding a provider key.</small></Card>}</div></Shell>}
''')
